export function parsePages(input,total){if(!input.trim())return Array.from({length:total},(_,i)=>i+1);const result=new Set();for(const part of input.split(',')){const match=part.trim().match(/^(\d+)(?:\s*-\s*(\d+))?$/);if(!match)throw new Error('Use page numbers such as 1, 3-5.');const start=Number(match[1]),end=Number(match[2]||match[1]);if(start<1||end>total||end<start)throw new Error(`Choose pages between 1 and ${total}, with ranges in ascending order.`);for(let n=start;n<=end;n++)result.add(n);}return [...result].sort((a,b)=>a-b);}
export function renderSize(viewport,dpi){const width=Math.ceil(viewport.width*dpi/72),height=Math.ceil(viewport.height*dpi/72);if(width>16384||height>16384||width*height>40000000)throw new Error('This page is too large at the selected DPI. Choose a lower resolution (maximum 40 megapixels per page).');return{width,height};}
